class GeneratedStrategy(Strategy):
    sma_window = 24
    rank_window = 16
    decay_window = 4

    def init(self):
        def alpha_func(close, sma_window, rank_window, decay_window):
            c = pd.Series(close).astype(float)

            sma_c = c.rolling(int(sma_window)).mean()
            price_dev = (c - sma_c) / (sma_c + 1e-8)

            def ts_rank_last(s):
                r = s.rank()
                return r.iloc[-1] / (len(s) + 1e-8)

            tsr = c.rolling(int(rank_window)).apply(ts_rank_last, raw=False)

            d = int(decay_window)
            weights = np.arange(1, d + 1, dtype=float)
            wsum = weights.sum() + 1e-8

            def decay_linear_last(s):
                arr = np.asarray(s, dtype=float)
                if len(arr) != d:
                    return np.nan
                return float(np.dot(arr, weights) / wsum)

            decayed = tsr.rolling(d).apply(decay_linear_last, raw=False)

            alpha = price_dev + decayed
            return alpha.to_numpy(dtype=float)

        self.alpha = self.I(
            alpha_func,
            self.data.Close,
            self.sma_window,
            self.rank_window,
            self.decay_window
        )

    def next(self):
        a = self.alpha[-1]
        if np.isnan(a):
